def create_current_school_year_and_enrollments(apps, schema_editor):
    SchoolYear = apps.get_model('core', 'SchoolYear')
    ChildEnrollment = apps.get_model('core', 'ChildEnrollment')
    Child = apps.get_model('children', 'Child')

    today = timezone.localdate()
    start_year = (
        today.year
        if today.month >= 9 or today.month > 6
        else today.year - 1
    )
    start_date = date(start_year, 9, 1)
    end_date = date(
        start_year + 1,
        6,
        monthrange(start_year + 1, 6)[1],
    )
    school_year = SchoolYear.objects.create(
        start_date=start_date,
        end_date=end_date,
        is_active=True,
    )

    ChildEnrollment.objects.bulk_create(
        [
            ChildEnrollment(
                child_id=child.pk,
                school_year_id=school_year.pk,
                classroom_id=child.classroom_id,
                attendance_formula=child.attendance_formula,
            )
            for child in Child.objects.all().iterator()
        ]
    )


def restore_current_year_assignments(apps, schema_editor):
    SchoolYear = apps.get_model('core', 'SchoolYear')
    ChildEnrollment = apps.get_model('core', 'ChildEnrollment')
    Child = apps.get_model('children', 'Child')
    active_year = SchoolYear.objects.filter(is_active=True).first()
    if active_year is None:
        return

    for enrollment in ChildEnrollment.objects.filter(
        school_year_id=active_year.pk,
    ).iterator():
        Child.objects.filter(pk=enrollment.child_id).update(
            classroom_id=enrollment.classroom_id,
            attendance_formula=enrollment.attendance_formula,
        )


